import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.util.*;
public class StandardizationCenterActivity extends Activity{private android.content.SharedPreferences p;private Spinner standard;private EditText org,resp,sources,quality,sharing,backup,target,schedule;@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);p=getSharedPreferences("standardisation_plan",0);setContentView(build());}private android.view.View build(){LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Centre de standardisation",28,true));r.addView(Ui.text(this,"Projet de mise à niveau de bases de données culturelles. Outil de préparation et de suivi : il ne constitue pas une certification officielle du MCC.",14,false));LinearLayout n=Ui.panel(this);n.addView(Ui.text(this,"1 · Norme sectorielle reconnue",21,true));String[] a={"MétaMusique","Arts de la scène","Cinéma","Livre — pour les éditeurs","Exposition dans un contexte muséal"};standard=new Spinner(this);standard.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a));standard.setSelection(p.getInt("standard",0));n.addView(standard);Button guide=Ui.secondary(this,"Voir le guide des champs");guide.setOnClickListener(v->{String[] c={"METAMUSIQUE","SCENE","CINEMA","LIVRE","MUSEE"};Intent i=new Intent(this,SectorGuideActivity.class);i.putExtra("sector",c[standard.getSelectedItemPosition()]);startActivity(i);});n.addView(guide);r.addView(n);LinearLayout flow=Ui.panel(this);flow.addView(Ui.text(this,"2 · Parcours technique",21,true));flow.addView(Ui.text(this,"IMPORTER → CARTOGRAPHIER → DIAGNOSTIQUER → NORMALISER → VALIDER HUMAINEMENT → EXPORTER → PARTAGER → MESURER",14,true));Button timeline=Ui.primary(this,"Planifier l’échéancier (maximum 12 mois)");timeline.setOnClickListener(v->startActivity(new Intent(this,ProjectTimelineActivity.class)));flow.addView(timeline);r.addView(flow);LinearLayout plan=Ui.panel(this);plan.addView(Ui.text(this,"3 · Plan de gestion des données",21,true));org=f(plan,"Organisation","org");resp=f(plan,"Responsable des données","resp");sources=f(plan,"Sources et provenance des données","sources");quality=f(plan,"Méthode de contrôle qualité","quality");sharing=f(plan,"Partage / données ouvertes / partenaires","sharing");backup=f(plan,"Sauvegardes, versions, conservation","backup");target=f(plan,"Cible mesurable de standardisation","target");schedule=f(plan,"Échéancier global ≤ 12 mois","schedule");Button save=Ui.primary(this,"Enregistrer le plan");save.setOnClickListener(v->save());plan.addView(save);r.addView(plan);LinearLayout dossier=Ui.panel(this);dossier.addView(Ui.text(this,"4 · Dossier de subvention",21,true));Button budget=Ui.primary(this,"Calculateur budgétaire");budget.setOnClickListener(v->startActivity(new Intent(this,BudgetActivity.class)));dossier.addView(budget);Button checklist=Ui.secondary(this,"Liste de contrôle du dossier");checklist.setOnClickListener(v->startActivity(new Intent(this,ApplicationChecklistActivity.class)));dossier.addView(checklist);Button team=Ui.secondary(this,"Équipe et capacité de réalisation");team.setOnClickListener(v->startActivity(new Intent(this,TeamCapacityActivity.class)));dossier.addView(team);r.addView(dossier);LinearLayout report=Ui.panel(this);report.addView(Ui.text(this,"5 · Mesures et reddition de comptes",21,true));Button evidence=Ui.primary(this,"Preuves et résultats");evidence.setOnClickListener(v->startActivity(new Intent(this,ProjectEvidenceActivity.class)));report.addView(evidence);report.addView(Ui.text(this,"Suivre : données totales, données standardisées, nouvelles données, pourcentage standardisé, modalités de partage, partenaires, résultats et écarts.",13,false));r.addView(report);return Ui.wrap(this,r);}private EditText f(LinearLayout p0,String h,String k){EditText e=Ui.field(this,h,p.getString(k,""));p0.addView(e);return e;}private void save(){p.edit().putInt("standard",standard.getSelectedItemPosition()).putString("org",org.getText().toString()).putString("resp",resp.getText().toString()).putString("sources",sources.getText().toString()).putString("quality",quality.getText().toString()).putString("sharing",sharing.getText().toString()).putString("backup",backup.getText().toString()).putString("target",target.getText().toString()).putString("schedule",schedule.getText().toString()).apply();Toast.makeText(this,"Plan enregistré localement",Toast.LENGTH_SHORT).show();}}
